import{c as d,Q as a,j as e,m as r}from"./chunks/framework.DOi4mjdC.js";const l="/assets/mmad.BGhHwfF3.png",o="/assets/mmad-2.DSgQG-LD.png",i="/assets/mmad-mx.BmxDjEnF.png",s="/assets/repeat-times-21.DtlZcFbq.png",x=JSON.parse('{"title":"MmadBitMode","description":"","frontmatter":{},"headers":[{"level":1,"title":"MmadBitMode","slug":"mmadbitmode"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/矩阵计算（ISASI）/矩阵计算/MmadBitMode.md","filePath":"api/SIMD-API/基础API/矩阵计算（ISASI）/矩阵计算/MmadBitMode.md"}'),n={name:"api/SIMD-API/基础API/矩阵计算（ISASI）/矩阵计算/MmadBitMode.md"};function p(m,t,f,_,c,h){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="mmadbitmode" tabindex="-1">MmadBitMode <a class="header-anchor" href="#mmadbitmode" aria-label="Permalink to &quot;MmadBitMode&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持（ 不传入bias的原型 ）</th><th>是否支持（ 传入bias的原型 ）</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td><td>x</td></tr><tr><td>Kirin X90</td><td>x</td><td>x</td></tr><tr><td>Kirin 9030</td><td>x</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>**功能一：**完成矩阵乘加（C += A * B）操作。矩阵ABC分别为A2/B2/CO1中的数据。</p><ul><li><p>ABC矩阵的数据排布格式分别为ZZ，ZN，NZ。数据排布格式详解请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/guide/%E6%8A%80%E6%9C%AF%E9%99%84%E5%BD%95/%E6%A6%82%E5%BF%B5%E5%8E%9F%E7%90%86%E5%92%8C%E6%9C%AF%E8%AF%AD/%E7%A5%9E%E7%BB%8F%E7%BD%91%E7%BB%9C%E5%92%8C%E7%AE%97%E5%AD%90/%E6%95%B0%E6%8D%AE%E6%8E%92%E5%B8%83%E6%A0%BC%E5%BC%8F.md" target="_blank" rel="noreferrer">数据排布格式</a>。</p><p>下图中每个小方格代表一个分形矩阵，Z字形的黑色线条代表数据的排列顺序，起始点是左上角，终点是右下角。</p><p>矩阵A：每个分形矩阵内部是行主序，分形矩阵之间是行主序。简称小Z大Z格式。分形shape为16 x (32B/sizeof(AType))，大小为512Byte。</p><p>矩阵B：每个分形矩阵内部是列主序，分形矩阵之间是行主序。简称小N大Z格式。分形shape为 (32B/sizeof(BType)) x 16，大小为512Byte。</p><p>矩阵C：每个分形矩阵内部是行主序，分形矩阵之间是列主序。简称小Z大N格式。分形shape为16 x 16，大小为256个元素。</p><p><img src="'+l+`" alt=""></p><p>以下是一个简单的例子，假设分形矩阵的大小是2x2（并不符合真实情况，仅作为示例），矩阵ABC的大小都是4x4。</p></li></ul><table tabindex="0"><thead><tr><th>0</th><th>1</th><th>2</th><th>3</th></tr></thead><tbody><tr><td>4</td><td>5</td><td>6</td><td>7</td></tr><tr><td>8</td><td>9</td><td>10</td><td>11</td></tr><tr><td>12</td><td>13</td><td>14</td><td>15</td></tr></tbody></table><pre><code>矩阵A的排列顺序：0，1，4，5，2，3，6，7，8，9，12，13，10，11，14，15。

矩阵B的排列顺序：0，4，1，5，2，6，3，7，8，12，9，13，10，14，11，15。

矩阵C的排列顺序：0，1，4，5，8，9，12，13，2，3，6，7，10，11，14，15。
</code></pre><ul><li><p>ABC矩阵的数据排布格式分别为NZ，ZN，NZ。</p><p>矩阵A：每个分形矩阵内部是行主序，分形矩阵之间是列主序。简称小Z大N格式。其shape为16 x (32B/sizeof(AType))，大小为512Byte。</p><p>矩阵B：每个分形矩阵内部是列主序，分形矩阵之间是行主序。简称小N大Z格式。其shape为 (32B/sizeof(BType)) x 16，大小为512Byte。</p><p>矩阵C：每个分形矩阵内部是行主序，分形矩阵之间是列主序。简称小Z大N格式。其shape为16 x 16，大小为256个元素。</p><p><img src="`+o+`" alt=""></p><p>以下是一个简单的例子，假设分形矩阵的大小是2x2（并不符合真实情况，仅作为示例），矩阵ABC的大小都是4x4。</p></li></ul><table tabindex="0"><thead><tr><th>0</th><th>1</th><th>2</th><th>3</th></tr></thead><tbody><tr><td>4</td><td>5</td><td>6</td><td>7</td></tr><tr><td>8</td><td>9</td><td>10</td><td>11</td></tr><tr><td>12</td><td>13</td><td>14</td><td>15</td></tr></tbody></table><pre><code>矩阵A的排列顺序:0，1，4，5，8，9，12，13，2，3，6，7，10，11，14，15。

矩阵B的排列顺序:0，4，1，5，2，6，3，7，8，12，9，13，10，14，11，15。

矩阵C的排列顺序:0，1，4，5，8，9，12，13，2，3，6，7，10，11，14，15。
</code></pre><p>**功能二：**针对Ascend 950PR/Ascend 950DT，还支持包含缩放功能的矩阵乘，公式如下：C = (ScaleA ⊗ A) ∗ (ScaleB ⊗ B) + C。ScaleA和ScaleB通过LoadData2DMX接口载入。</p><ul><li>ScaleA的分形格式为小Z大Z ，shape为（16，2），数据类型为fp8_e8m0_t。</li><li>ScaleB的分形格式为小N大N，shape为 （2，16），数据类型为fp8_e8m0_t。</li></ul><p>以AB矩阵均为fp4x2_e2m1_t数据类型为例，下图展示了ScaleA、ScaleB的分形排布格式和缩放功能原理：</p><p><img src="`+i+'" alt=""></p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>不传入bias</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, typename U, typename S&gt;</span></span>\n<span class="line"><span>__aicore__ inline void Mmad(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;U&gt;&amp; fm, const LocalTensor&lt;S&gt;&amp; filter, const MmadBitModeParams&amp; mmadParams)</span></span></code></pre></div></li><li><p>传入bias</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, typename U, typename S, typename V&gt;</span></span>\n<span class="line"><span>__aicore__ inline void Mmad(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;U&gt;&amp; fm, const LocalTensor&lt;S&gt;&amp; filter, const LocalTensor&lt;V&gt;&amp; bias, const MmadBitModeParams&amp; mmadParams)</span></span></code></pre></div></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>目的操作数的数据类型。</td></tr><tr><td>U</td><td>左矩阵的数据类型。</td></tr><tr><td>S</td><td>右矩阵的数据类型。</td></tr><tr><td>V</td><td>Bias矩阵的数据类型。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，结果矩阵，类型为LocalTensor，支持的TPosition为CO1。 LocalTensor的起始地址需要256个元素对齐。</td></tr><tr><td>fm</td><td>输入</td><td>源操作数，左矩阵a，类型为LocalTensor，支持的TPosition为A2。 LocalTensor的起始地址需要512字节对齐。</td></tr><tr><td>filter</td><td>输入</td><td>源操作数，右矩阵b，类型为LocalTensor，支持的TPosition为B2。 LocalTensor的起始地址需要512字节对齐。</td></tr><tr><td>bias</td><td>输入</td><td>源操作数，bias矩阵，类型为LocalTensor，支持的TPosition为C2、CO1。 LocalTensor的起始地址需要128字节对齐。</td></tr><tr><td>mmadParams</td><td>输入</td><td>矩阵乘相关参数，该参数类型的具体定义请参考${INSTALL_DIR}/include/ascendc/basic_api/interface/kernel_struct_mm.h，${INSTALL_DIR}请替换为CANN软件安装后文件存储路径。 MmadBitModeParams，参数说明请参考表3。</td></tr></tbody></table><p><strong>表 3</strong> MmadBitModeParams类参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>config0</td><td>uint64_t类型，与MmadBitModeConfig0位域（bit-field）结构体类型参数config0BitMode组成联合体（union），初始化为0，可以使用类对象的GetConfig0()函数获取其值。</td></tr><tr><td>config0BitMode</td><td>MmadBitModeConfig0位域（bit-field）结构体类型，参数参考表4，与config0组成联合体（union）。</td></tr></tbody></table><p>MmadBitModeParams类参数设计思想说明：</p><p>联合体（union）是一种特殊的数据结构，允许在相同的内存位置存储不同的数据类型。union的所有成员共享同一块内存空间，大小由最大成员决定，同一时间只能使用一个成员。</p><p>位域（bit-field）是一种特殊的类成员，允许精确控制结构体中成员变量所占用的内存位数。结构体中成员变量从上到下对应内存中从低位到高位。</p><p>MmadBitModeParams类使用union与bit-field方法，采用bit位表达参数类型，使用bit-field结构体自动处理入参的bit位数，并利用union的特性实现多参数融合传递，仅需传递一个入参即可包含全部所需信息，对应底层接口仅需要接收一个参数。同时，当需要修改参数中某一bit位的值时，仅需要通过循环和位运算即可实现，不需要重新传入参数，减少了scalar计算，实现性能提升。</p><p>MmadBitModeParams类可以直接使用MmadBitModeParams结构体类型对象初始化：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline MmadBitModeParams(const MmadBitModeParams &amp;mmadParams_);</span></span></code></pre></div><p>也可以使用各参数的Set函数修改参数值，并且由于使用了联合体，还可以对congfig0直接进行逐bit位修改来修改参数。</p><p><strong>表 4</strong> MmadBitModeConfig0结构体参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>m</td><td>左矩阵Height，取值范围：m∈[0, 4095] 。默认值为0。 该参数是位域结构体的最低位参数，占用12bit，可以使用MmadBitModeParams类对象的SetM()函数设置其值，使用GetM()函数获取其值。</td></tr><tr><td>k</td><td>右矩阵Width，取值范围：n∈[0, 4095] 。默认值为0。 该参数是位域结构体的第二低位参数，占用12bit，可以使用MmadBitModeParams类对象的SetK()函数设置其值，使用GetK()函数获取其值。</td></tr><tr><td>n</td><td>左矩阵Width、右矩阵Height，取值范围：k∈[0, 4095] 。默认值为0。 该参数是位域结构体的第三低位参数，占用12bit，可以使用MmadBitModeParams类对象的SetN()函数设置其值，使用GetN()函数获取其值。</td></tr><tr><td>unitFlag</td><td>预留参数。为后续的功能做保留，开发者暂时无需关注，使用默认值即可。 该参数是位域结构体的第四低位参数，占用2bit，可以使用MmadBitModeParams类对象的SetUnitFlag()函数设置其值，使用GetUnitFlag()函数获取其值。</td></tr><tr><td>disableGemv</td><td>M = 1时，用于配置Mmad计算是否开启GEMV。当输入为false时，表示开启GEMV；反之，输入为true时，表示关闭GEMV。 GEMV（General Matrix-Vector Multiplication）表示实现矩阵和向量的乘积，开启GEMV后，Mmad API 从L0A Buffer读取数据时，数据将以ND格式进行读取，而不会将其视为ZZ格式。 该参数是位域结构体的第五低位参数，占用1bit，可以使用MmadBitModeParams类对象的SetDisableGemv()函数设置其值，使用GetDisableGemv()函数获取其值。</td></tr><tr><td>cmatrixSource</td><td>配置C矩阵初始值是否来源于C2（存放Bias的硬件缓存区）。默认值为false。 false：来源于CO1； true：来源于C2。 注意：带bias输入的接口配置该参数无效，会根据bias输入的位置来判断C矩阵初始值是否来源于CO1还是C2。 该参数是位域结构体的第六低位参数，占用1bit，可以使用MmadBitModeParams类对象的SetCmatrixSource()函数设置其值，使用GetCmatrixSource()函数获取其值。</td></tr><tr><td>cmatrixInitVal</td><td>配置C矩阵初始值是否为0。默认值true。 true：C矩阵初始值为0；false：C矩阵初始值通过cmatrixSource参数进行配置。 该参数是位域结构体的最高位参数，占用1bit，可以使用MmadBitModeParams类对象的SetCmatrixInitVal()函数设置其值，使用GetCmatrixInitVal()函数获取其值。</td></tr></tbody></table><p>MmadBitModeConfig0结构体参数的含义与MmadBitModeParams结构体中的同名参数含义相同，具体参考<a href="./Mmad.html#table15780447181917">表3</a>。</p><p><strong>表 5</strong> dst、fm、filter支持的精度类型组合（Ascend 950PR/Ascend 950DT）</p><table tabindex="0"><thead><tr><th>左矩阵fm type</th><th>右矩阵filter type</th><th>结果矩阵dst type</th><th>备注</th></tr></thead><tbody><tr><td>int8_t</td><td>int8_t</td><td>int32_t</td><td>仅支持不含缩放的矩阵乘</td></tr><tr><td>half</td><td>half</td><td>float</td><td>仅支持不含缩放的矩阵乘</td></tr><tr><td>float</td><td>float</td><td>float</td><td>仅支持不含缩放的矩阵乘</td></tr><tr><td>bfloat16_t</td><td>bfloat16_t</td><td>float</td><td>仅支持不含缩放的矩阵乘</td></tr><tr><td>fp8_e4m3fn_t</td><td>fp8_e4m3fn_t</td><td>float</td><td>仅支持不含缩放的矩阵乘</td></tr><tr><td>fp8_e4m3fn_t</td><td>fp8_e5m2_t</td><td>float</td><td>仅支持不含缩放的矩阵乘</td></tr><tr><td>fp8_e5m2_t</td><td>fp8_e4m3fn_t</td><td>float</td><td>仅支持不含缩放的矩阵乘</td></tr><tr><td>fp8_e5m2_t</td><td>fp8_e5m2_t</td><td>float</td><td>仅支持不含缩放的矩阵乘</td></tr><tr><td>hifloat8_t</td><td>hifloat8_t</td><td>float</td><td>仅支持不含缩放的矩阵乘</td></tr><tr><td>fp4x2_e1m2_t</td><td>fp4x2_e1m2_t</td><td>float</td><td>仅支持包含缩放的矩阵乘</td></tr><tr><td>fp4x2_e2m1_t</td><td>fp4x2_e1m2_t</td><td>float</td><td>仅支持包含缩放的矩阵乘</td></tr><tr><td>fp4x2_e1m2_t</td><td>fp4x2_e2m1_t</td><td>float</td><td>仅支持包含缩放的矩阵乘</td></tr><tr><td>fp4x2_e2m1_t</td><td>fp4x2_e2m1_t</td><td>float</td><td>仅支持包含缩放的矩阵乘</td></tr><tr><td>AscendC::mx_fp8_e4m3_t</td><td>AscendC::mx_fp8_e4m3_t</td><td>float</td><td>仅支持包含缩放的矩阵乘</td></tr><tr><td>AscendC::mx_fp8_e4m3_t</td><td>AscendC::mx_fp8_e5m2_t</td><td>float</td><td>仅支持包含缩放的矩阵乘</td></tr><tr><td>AscendC::mx_fp8_e5m2_t</td><td>AscendC::mx_fp8_e4m3_t</td><td>float</td><td>仅支持包含缩放的矩阵乘</td></tr><tr><td>AscendC::mx_fp8_e5m2_t</td><td>AscendC::mx_fp8_e5m2_t</td><td>float</td><td>仅支持包含缩放的矩阵乘</td></tr></tbody></table><p><strong>表 6</strong> dst、fm、filter、bias支持的精度类型组合（Ascend 950PR/Ascend 950DT）</p><table tabindex="0"><thead><tr><th>左矩阵fm type</th><th>右矩阵filter type</th><th>bias type</th><th>结果矩阵dst type</th><th>备注</th></tr></thead><tbody><tr><td>int8_t</td><td>int8_t</td><td>int32_t</td><td>int32_t</td><td>仅支持不含缩放的矩阵乘</td></tr><tr><td>half</td><td>half</td><td>float</td><td>float</td><td>仅支持不含缩放的矩阵乘</td></tr><tr><td>float</td><td>float</td><td>float</td><td>float</td><td>仅支持不含缩放的矩阵乘</td></tr><tr><td>bfloat16_t</td><td>bfloat16_t</td><td>float</td><td>float</td><td>仅支持不含缩放的矩阵乘</td></tr><tr><td>fp8_e4m3fn_t</td><td>fp8_e4m3fn_t</td><td>float</td><td>float</td><td>仅支持不含缩放的矩阵乘</td></tr><tr><td>fp8_e4m3fn_t</td><td>fp8_e5m2_t</td><td>float</td><td>float</td><td>仅支持不含缩放的矩阵乘</td></tr><tr><td>fp8_e5m2_t</td><td>fp8_e4m3fn_t</td><td>float</td><td>float</td><td>仅支持不含缩放的矩阵乘</td></tr><tr><td>fp8_e5m2_t</td><td>fp8_e5m2_t</td><td>float</td><td>float</td><td>仅支持不含缩放的矩阵乘</td></tr><tr><td>hifloat8_t</td><td>hifloat8_t</td><td>float</td><td>float</td><td>仅支持不含缩放的矩阵乘</td></tr><tr><td>fp4x2_e1m2_t</td><td>fp4x2_e1m2_t</td><td>float</td><td>float</td><td>仅支持包含缩放的矩阵乘</td></tr><tr><td>fp4x2_e2m1_t</td><td>fp4x2_e1m2_t</td><td>float</td><td>float</td><td>仅支持包含缩放的矩阵乘</td></tr><tr><td>fp4x2_e1m2_t</td><td>fp4x2_e2m1_t</td><td>float</td><td>float</td><td>仅支持包含缩放的矩阵乘</td></tr><tr><td>fp4x2_e2m1_t</td><td>fp4x2_e2m1_t</td><td>float</td><td>float</td><td>仅支持包含缩放的矩阵乘</td></tr><tr><td>AscendC::mx_fp8_e4m3_t</td><td>AscendC::mx_fp8_e4m3_t</td><td>float</td><td>float</td><td>仅支持包含缩放的矩阵乘</td></tr><tr><td>AscendC::mx_fp8_e4m3_t</td><td>AscendC::mx_fp8_e5m2_t</td><td>float</td><td>float</td><td>仅支持包含缩放的矩阵乘</td></tr><tr><td>AscendC::mx_fp8_e5m2_t</td><td>AscendC::mx_fp8_e4m3_t</td><td>float</td><td>float</td><td>仅支持包含缩放的矩阵乘</td></tr><tr><td>AscendC::mx_fp8_e5m2_t</td><td>AscendC::mx_fp8_e5m2_t</td><td>float</td><td>float</td><td>仅支持包含缩放的矩阵乘</td></tr></tbody></table><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p>dst只支持位于CO1，fm只支持位于A2，filter只支持位于B2。</p></li><li><p>当M、K、N中的任意一个值为0时，该指令不会被执行。</p></li><li><p>当M = 1时，会默认开启GEMV（General Matrix-Vector Multiplication）功能。在这种情况下，Mmad API从L0A Buffer读取数据时，会以ND格式进行读取，而不会将其视为ZZ格式。所以此时左矩阵需要直接按照ND格式进行排布。针对Ascend 950PR/Ascend 950DT，可以通过设置MmadBitModeParams的disableGemv参数为true，将该功能关闭。</p></li><li><p>操作数地址对齐要求请参见<a href="./../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</p></li><li><p>通过一个具体的示例来介绍无效数据与有效数据的排布方式。</p><p>数据为half类型，当M=30，K=70，N=40的时候，A2中有2x5个16x16矩阵，B2中有5x3个16x16矩阵，CO1中有2x3个16x16矩阵。在这种场景下M、K和N都不是16的倍数，A2中右下角的矩阵实际有效的数据只有14x6个，但是也需要占一个16x16矩阵的空间，其他无效数据在计算中会被忽略。一个16x16分形的数据块中，无效数据与有效数据排布的方式示意如下：</p><p><img src="'+s+'" alt=""></p></li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>不含矩阵乘偏置的样例请参考<a href="https://gitee.com/ascend/samples/tree/master/operator/ascendc/0_introduction/20_mmad_kernellaunch/MmadInvocation" target="_blank" rel="noreferrer">Mmad样例</a>。</p><p>包含矩阵乘偏置的样例请参考<a href="https://gitee.com/ascend/samples/blob/master/operator/ascendc/0_introduction/20_mmad_kernellaunch/MmadBiasInvocation/" target="_blank" rel="noreferrer">包含矩阵乘偏置的Mmad样例</a>。</p>',43)])])}const M=d(n,[["render",p]]);export{x as __pageData,M as default};
